import base64,os,sys,subprocess
from pathlib import Path
if os.geteuid()!=0 or Path('/sys/class/dmi/id/product_uuid').read_text().strip().lower()!='7632fb78-37a0-f645-97c0-dc322c50b002':raise SystemExit('WRONG_TEST_VM_OR_ROOT_REQUIRED')
if sys.argv[1:] not in (['--apply'],['--check']):raise SystemExit('ACTION_REQUIRED')
result=subprocess.run(['docker','exec','-i','cabal_main','python3','-',sys.argv[1]],input=base64.b64decode('',validate=True))
raise SystemExit(result.returncode)
